// Прод, только чтение: браузер, все не-GET запросы заблокированы; navigator.share подменён (ничего не отправляется).
import { test, expect, type APIRequestContext } from '@playwright/test';
import { readSitemap, rawHtml, jsonLd, listingNode, blockNonGet, ORIGIN } from './ssr-seo.helpers';

test.use({ serviceWorkers: 'block' });

/** Первое объявление из sitemap с ≥ minImages картинками в JSON-LD и названием без крайних пробелов. */
async function pickListing(request: APIRequestContext, minImages: number) {
  const sm = await readSitemap(request);
  for (const id of sm.listingIds.slice(0, 60)) {
    const node = listingNode(jsonLd((await rawHtml(request, `/businessdetail?id=${id}`)).html));
    const name = String(node?.['name'] ?? '');
    const images = [node?.['image'] ?? []].flat();
    if (name && name === name.trim() && !/\s{2}/.test(name) && images.length >= minImages) return { id, name };
  }
  return undefined;
}

test.describe('SSR и SEO публичных страниц — hydration', () => {
  test('Галерея объявления после hydration: «המדיה הבאה» меняет главную картинку #b3dc2e @desktop @prod-safe', async ({ page, request }) => {
    const listing = await pickListing(request, 2);
    expect(listing, 'объявление с ≥ 2 картинками в первых 60 из sitemap').toBeTruthy();
    const { id, name } = listing!;

    await blockNonGet(page);
    await page.goto(`/businessdetail?id=${id}`);
    await expect(page.getByRole('img', { name: `${name} - 1`, exact: true })).toBeVisible({ timeout: 30_000 });

    // Кнопка главной галереи — первая «המדיה הבאה» на странице (галереи карточек рекомендаций ниже).
    await page.getByRole('button', { name: 'המדיה הבאה', exact: true }).first().click();
    await expect(page.getByRole('img', { name: `${name} - 2`, exact: true })).toBeVisible();
  });

  test('«שיתוף המודעה» после hydration вызывает navigator.share с короткой ссылкой /b/<код> #b3dc2e @desktop @prod-safe', async ({ page, request }) => {
    const listing = await pickListing(request, 0);
    expect(listing, 'объявление в sitemap').toBeTruthy();
    const { id, name } = listing!;

    await page.addInitScript(() => {
      (window as unknown as { __qaShared: unknown[] }).__qaShared = [];
      Object.defineProperty(navigator, 'share', {
        configurable: true,
        value: async (data: unknown) => { (window as unknown as { __qaShared: unknown[] }).__qaShared.push(data); },
      });
      Object.defineProperty(navigator, 'canShare', { configurable: true, value: () => true });
    });
    await blockNonGet(page);
    await page.goto(`/businessdetail?id=${id}`);

    await page.getByRole('button', { name: `שיתוף המודעה ${name}`, exact: true }).click();
    await expect
      .poll(() => page.evaluate(() => (window as unknown as { __qaShared: { url?: string }[] }).__qaShared.map((d) => d.url)))
      .toEqual([`${ORIGIN}/b/${id.slice(0, 8)}`]);
  });
});
